//! 📦️ Actual empty, short and full native backing remains with its funded Original caller until exact release.
use semio_framework_job::*;
#[path="../../../../🧪️testing/📬️payload/🦀️.rs"]
mod original_payload;
#[global_allocator]
static ORIGINAL_PHYSICAL_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn close(original:&mut original_payload::OriginalTestPayload,grant:RetainedCloneGrant)->(bool,RetainedCloneProgress,(usize,usize)){let(done,heap)=original_payload::observe(||original.advance(grant,|builder,cx|Ok(builder.close_step(cx)?)).unwrap());(done,original.caller.receipt(),heap)}
#[test]
fn retained_payload_physical_close_preserves_short_pages_until_the_exact_backing_grant(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧪️tests/🧫️fixtures/📦️physical-close/🔣️.json")).unwrap();assert_eq!(fixture["pageBytes"],JOB_PAYLOAD_PAGE_BYTES);
 for stream in[JobPayloadStream::CheckpointState,JobPayloadStream::Preview,JobPayloadStream::CommitState,JobPayloadStream::CommitOutput,JobPayloadStream::Fault]{for row in fixture["cases"].as_array().unwrap(){let bytes=vec![42;row["logicalBytes"].as_u64().unwrap()as usize];let mut original=original_payload::OriginalTestPayload::admit_single_page(OperationId(90010+stream as u64),Generation(21),stream,&bytes,JOB_PAYLOAD_PAGE_BYTES);let payload=original.builder.published().unwrap();assert_eq!(payload.page_count(),1);assert_eq!(payload.page_capacity_bytes(0),Some(JOB_PAYLOAD_PAGE_BYTES));assert_eq!(payload.len(),bytes.len());let pointer=payload.page(0).unwrap().as_ptr();let insufficient=row["insufficientGrant"].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:0,maximum_release_bytes:JOB_PAYLOAD_PAGE_BYTES,maximum_depth:64};
  for denied in[RetainedCloneGrant{maximum_release_bytes:0,..grant},RetainedCloneGrant{maximum_items:0,..grant}]{let(done,receipt,heap)=close(&mut original,denied);assert!(!done);assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));}
  assert_eq!(original.builder.published().unwrap().next_close_byte_demand(),JOB_PAYLOAD_PAGE_BYTES);
  for _ in 0..4{let(done,receipt,heap)=close(&mut original,RetainedCloneGrant{maximum_release_bytes:insufficient,..grant});assert!(!done);assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));let payload=original.builder.published().unwrap();assert_eq!(payload.page(0).unwrap().as_ptr(),pointer);assert_eq!(payload.page(0).unwrap(),bytes);assert_eq!(payload.allocated_capacity_bytes(),JOB_PAYLOAD_PAGE_BYTES);}
  let(done,refused,heap)=close(&mut original,RetainedCloneGrant{maximum_release_bytes:insufficient,..grant});assert!(!done);assert_eq!(heap,(0,0));let retained_pointer=original.builder.published().unwrap().page(0).map(|page|page.as_ptr())==Some(pointer);let(done,released,heap)=close(&mut original,grant);assert!(!done);assert_eq!(heap,(0,JOB_PAYLOAD_PAGE_BYTES));let payload=original.builder.original().unwrap();assert_eq!(payload.next_close_byte_demand(),JobPayloadAuthority::admission_demand().capacity_bytes);let remaining_logical_bytes=payload.len();let remaining_pages=payload.page_count();
  let actual=serde_json::json!({"refusedItems":refused.copied_items,"refusedBytes":refused.released_bytes,"retainedPointer":retained_pointer,"releasedItems":released.copied_items,"releasedBytes":released.released_bytes,"remainingLogicalBytes":remaining_logical_bytes,"remainingPages":remaining_pages,"chargedTotal":refused.released_bytes+released.released_bytes});assert_eq!(actual,fixture["expected"]);original.close();let receipt=original.caller.cumulative_receipt();assert_eq!(receipt.retained_capacity_bytes,receipt.released_bytes);assert_eq!(original_payload::observe(||drop(original)).1,(0,0));eprintln!("[DEBUG] actual original physical page stream={stream:?} logical={} backing={} release={} samePointer={retained_pointer} repeatedShortGrant4 paidLedgerAndRoots={} terminalDrop0",bytes.len(),JOB_PAYLOAD_PAGE_BYTES,released.released_bytes,receipt.released_bytes);
 }}
}
